N = {}

N[1] = dict(
 short=("The Opening: praise, a promise of worship, and a daily request for the straight path.",
        "সূচনা: প্রশংসা, ইবাদতের অঙ্গীকার, আর সরল পথের জন্য প্রতিদিনের প্রার্থনা।"),
 ov=("Al-Fatihah is the opening of the Qur'an and the surah recited in every unit of prayer. It moves in three steps. First, praise: Allah is Lord of all the worlds, the Most Compassionate, the Most Merciful, Master of the Day of Judgement. Then a promise from us: “You alone we worship, and You alone we ask for help.” Finally a request: guide us to the straight path — the path of those You have blessed, not of those who earned anger or went astray.",
     "সূরা আল-ফাতিহা কুরআনের সূচনা, আর নামাজের প্রতিটি রাকাতে এটি পড়া হয়। এটি তিন ধাপে এগোয়। প্রথমে প্রশংসা: আল্লাহ সৃষ্টিজগতের রব, পরম করুণাময়, অতি দয়ালু, প্রতিদান দিবসের মালিক। তারপর আমাদের অঙ্গীকার: “আমরা শুধু আপনারই ‘ইবাদাত করি, এবং শুধু আপনারই সাহায্য প্রার্থনা করি” শেষে প্রার্থনা: আমাদের সরল পথ দেখাও — তাদের পথ, যাদের তুমি অনুগ্রহ করেছ; তাদের নয়, যারা ক্রোধের পাত্র হয়েছে বা পথভ্রষ্ট হয়েছে।"),
 flow=[(1,4,"Praise: Lord of the worlds, Compassionate, Merciful, Master of the Day","প্রশংসা: সৃষ্টিজগতের রব, করুণাময়, দয়ালু, প্রতিদান দিবসের মালিক"),
       (5,5,"Our promise: worship and help from Allah alone","আমাদের অঙ্গীকার: ইবাদত ও সাহায্য শুধু আল্লাহর কাছে"),
       (6,7,"Our request: guide us to the straight path","আমাদের প্রার্থনা: সরল পথ দেখাও")],
 concepts=[("Rabb","রব","Lord: the one who creates, owns, sustains and cares for.","রব: যিনি সৃষ্টি করেন, মালিক, প্রতিপালন ও তত্ত্বাবধান করেন।","1:2","q"),
           ("Ar-Rahman, ar-Rahim","আর-রহমান, আর-রহিম","Two names from the same root as mercy; they appear twice in seven verses.","রহমত শব্দমূল থেকে দুটি নাম; সাত আয়াতে দুবার এসেছে।","1:1, 1:3","q"),
           ("As-sirat al-mustaqim","আস-সিরাতুল মুস্তাকিম","The straight path: the way that leads to Allah, described by the people who walked it.","সরল পথ: যে পথ আল্লাহর কাছে পৌঁছায়, যারা সেই পথে চলেছেন তাদের মাধ্যমে বর্ণিত।","1:6–7","q")],
 take=(["Begin with praise before asking.","Worship and asking for help belong together, and both go to Allah alone (1:5).","Even people who pray every day keep asking for guidance; it is never ‘done’.","Mercy is mentioned before judgement."],
       ["চাওয়ার আগে প্রশংসা দিয়ে শুরু করো।","ইবাদত ও সাহায্য চাওয়া একসঙ্গে চলে, আর দুটিই শুধু আল্লাহর কাছে (১:৫)।","যারা প্রতিদিন নামাজ পড়ে, তারাও বারবার হেদায়েত চায়; এটি কখনো ‘শেষ’ হয় না।","বিচারের আগে রহমতের কথা বলা হয়েছে।"]),
 example=("Before a job interview, many of us ask Allah for help. Al-Fatihah suggests a pattern for any such moment: thank Him first, remind ourselves that we rely on Him, then ask to be guided to what is right — not only to what we want.",
          "চাকরির সাক্ষাৎকারের আগে আমরা অনেকে আল্লাহর সাহায্য চাই। সূরা আল-ফাতিহা এমন যেকোনো মুহূর্তের জন্য একটি ধারা দেখায়: আগে তাঁর প্রশংসা, তারপর মনে করা যে আমরা তাঁর ওপর নির্ভরশীল, তারপর যা সঠিক সেই পথ চাওয়া — শুধু যা আমরা চাই তা নয়।"))

N[32] = dict(
 short=("The Prostration: humility when reminded, the gifts of hearing, sight and hearts, and rising at night.",
        "সিজদা: স্মরণে বিনয়, শ্রবণ, দৃষ্টি ও অন্তরের নিয়ামত, আর রাতে জেগে ওঠা।"),
 ov=("As-Sajdah opens by saying the Book is, without doubt, from the Lord of the worlds. It describes Allah as Creator of the heavens and earth in six days, who began the human being from clay, shaped him, breathed into him of His spirit and gave him hearing, sight and hearts — “little it is that you give thanks”. It contrasts people who, when reminded of Allah's signs, fall down in prostration and leave their beds at night to call on their Lord in fear and hope, with those who turn away. No one knows the joy hidden for the first group. It mentions Musa receiving the Scripture and leaders who guided once they were patient and certain.",
     "সূরা আস-সাজদাহ শুরু হয় এই কথা দিয়ে যে, এই কিতাব নিঃসন্দেহে সৃষ্টিজগতের রবের পক্ষ থেকে। এতে আল্লাহকে বর্ণনা করা হয়েছে ছয় দিনে আসমান-জমিনের স্রষ্টা হিসেবে, যিনি মানুষকে মাটি থেকে সৃষ্টি শুরু করেছেন, গঠন দিয়েছেন, তাঁর পক্ষ থেকে রূহ ফুঁকে দিয়েছেন এবং শ্রবণ, দৃষ্টি ও অন্তর দিয়েছেন — “তোমরা খুব সামান্যই কৃতজ্ঞতা প্রকাশ কর”। তুলনা করা হয়েছে এমন লোকদের সঙ্গে, যাদের আল্লাহর নিদর্শন স্মরণ করানো হলে সিজদায় লুটিয়ে পড়ে এবং রাতে বিছানা ছেড়ে ভয় ও আশা নিয়ে রবকে ডাকে — আর যারা মুখ ফিরিয়ে নেয়। প্রথম দলের জন্য লুকানো আনন্দের কথা কেউ জানে না। মূসার কিতাব লাভ এবং ধৈর্য ও দৃঢ় বিশ্বাসের পর পথপ্রদর্শক নেতাদের কথাও এসেছে।"),
 flow=[(1,3,"The Book is from the Lord of the worlds","কিতাব সৃষ্টিজগতের রবের পক্ষ থেকে"),
       (4,9,"Creation of the heavens and of the human being; hearing, sight and hearts","আসমান ও মানুষের সৃষ্টি; শ্রবণ, দৃষ্টি ও অন্তর"),
       (10,14,"Doubts about resurrection; regret before their Lord","পুনরুত্থান নিয়ে সন্দেহ; রবের সামনে অনুশোচনা"),
       (15,22,"Those who prostrate and pray at night, and those who turn away","যারা সিজদা করে ও রাতে দোয়া করে, আর যারা মুখ ফেরায়"),
       (23,30,"Musa and the Scripture; patient leaders; signs in rain and crops","মূসা ও কিতাব; ধৈর্যশীল নেতা; বৃষ্টি ও ফসলে নিদর্শন")],
 concepts=[("Sajdah","সাজদাহ","Prostration: the believers' response when reminded of Allah's signs. Verse 15 is one of the places where readers customarily prostrate.","সিজদা: আল্লাহর নিদর্শন স্মরণ করানো হলে মুমিনদের সাড়া। ১৫ নম্বর আয়াত তিলাওয়াতের সিজদার একটি স্থান হিসেবে প্রচলিত।","32:15","q"),
           ("Fear and hope","ভয় ও আশা","Night prayer described as calling on Allah with both at once.","রাতের দোয়াকে একসঙ্গে দুটি অনুভূতি নিয়ে আল্লাহকে ডাকা হিসেবে বর্ণনা করা হয়েছে।","32:16","q"),
           ("A Day of a thousand years","হাজার বছরের এক দিন","Allah's affairs are measured differently from our counting of time.","আল্লাহর বিষয়ের পরিমাপ আমাদের সময় গণনা থেকে ভিন্ন।","32:5","q")],
 take=(["Hearing, sight and understanding are gifts that call for thanks (32:9).","Our first reaction to a reminder says a lot about our heart (32:15).","Quiet night prayer is honoured with a reward no one can imagine (32:16–17).","Leadership in faith comes from patience and certainty (32:24)."],
       ["শ্রবণ, দৃষ্টি ও বোধশক্তি এমন দান, যা কৃতজ্ঞতা দাবি করে (৩২:৯)।","উপদেশ শুনে আমাদের প্রথম প্রতিক্রিয়া অন্তরের অনেক কিছু বলে দেয় (৩২:১৫)।","নীরব রাতের ইবাদতের প্রতিদান এমন, যা কেউ কল্পনা করতে পারে না (৩২:১৬–১৭)।","ঈমানে নেতৃত্ব আসে ধৈর্য ও দৃঢ় বিশ্বাস থেকে (৩২:২৪)।"]),
 example=("Setting an alarm ten minutes before Fajr to make a short personal dua is a modest, practical way to “forsake their beds” that verse 16 describes.",
          "ফজরের দশ মিনিট আগে অ্যালার্ম দিয়ে উঠে ছোট্ট একটি ব্যক্তিগত দোয়া করা — ১৬ নম্বর আয়াতে বর্ণিত “তাদের পার্শ্বদেশ শয্যা হতে দূরে থাকে”-এর একটি সাধারণ, বাস্তব রূপ।"))

N[67] = dict(
 short=("The Sovereignty: life and death as a test, a flawless sky, and dependence on Allah for everything.",
        "রাজত্ব: পরীক্ষা হিসেবে জীবন ও মৃত্যু, ত্রুটিহীন আকাশ, আর সব কিছুতে আল্লাহর ওপর নির্ভরতা।"),
 ov=("Al-Mulk begins: blessed is He in whose hand is the dominion, who created death and life to test which of you is best in deeds. It invites us to look at the sky again and again and find no flaw. It then pictures the people of the Fire admitting, “If only we had listened or understood”, and promises forgiveness to those who fear their Lord unseen. The second half points to daily dependence: the earth made easy to walk on, birds held in the air by the Most Merciful, provision that only He can give, and water that only He can bring back if it sinks away.",
     "সূরা আল-মুলক শুরু হয়: বরকতময় তিনি, যাঁর হাতে রাজত্ব, যিনি মৃত্যু ও জীবন সৃষ্টি করেছেন পরীক্ষা করার জন্য — কে আমলে উত্তম। আকাশের দিকে বারবার তাকিয়ে কোনো ত্রুটি না পাওয়ার আমন্ত্রণ জানানো হয়েছে। তারপর জাহান্নামীদের স্বীকারোক্তির চিত্র — “যদি আমরা শুনতাম অথবা বিবেক-বুদ্ধি প্রয়োগ করতাম” — আর না দেখে রবকে ভয় করা লোকদের জন্য ক্ষমার প্রতিশ্রুতি। দ্বিতীয় অংশ দৈনন্দিন নির্ভরতার দিকে ইঙ্গিত করে: চলার জন্য সহজ করে দেওয়া জমিন, পরম দয়াময়ের ধরে রাখা উড়ন্ত পাখি, রিজিক যা শুধু তিনিই দিতে পারেন, আর পানি — মাটির নিচে চলে গেলে যা শুধু তিনিই ফিরিয়ে আনতে পারেন।"),
 flow=[(1,5,"Life and death as a test; look at the flawless sky","পরীক্ষা হিসেবে জীবন ও মৃত্যু; ত্রুটিহীন আকাশ দেখো"),
       (6,11,"The Fire and the regret of those who did not listen","জাহান্নাম ও যারা শোনেনি তাদের অনুশোচনা"),
       (12,15,"Fearing Allah unseen; He knows what is in hearts; the earth made easy","না দেখে আল্লাহভীতি; তিনি অন্তরের খবর জানেন; জমিন সহজ করা"),
       (16,24,"Safety, birds in the air, provision, the gifts of hearing and sight","নিরাপত্তা, আকাশে পাখি, রিজিক, শ্রবণ ও দৃষ্টির দান"),
       (25,30,"When is the promise? Trust in the Most Merciful; who brings water?","প্রতিশ্রুতি কবে? পরম দয়াময়ে ভরসা; পানি কে আনবে?")],
 concepts=[("Ahsanu 'amala","আহসানু আমালা","“Best in conduct”: the test is about the quality of deeds, not the quantity.","“আমলের দিক থেকে উত্তম”: পরীক্ষাটি আমলের মান নিয়ে, শুধু পরিমাণ নিয়ে নয়।","67:2","q"),
           ("Fearing Him unseen","না দেখে ভয়","Being mindful of Allah when no one else is watching.","যখন কেউ দেখছে না, তখনও আল্লাহর ব্যাপারে সচেতন থাকা।","67:12","q"),
           ("Listening and reasoning","শোনা ও বোঝা","The people of the Fire blame their failure to listen or think.","জাহান্নামীরা নিজেদের না শোনা ও না বোঝাকে দায়ী করবে।","67:10","q")],
 take=(["Life is a test of quality: “which of you is best in conduct” (67:2).","Looking closely at creation strengthens faith.","Private conduct matters most (67:12–13).","Water, food and safety are reminders that we depend on Allah every day (67:21, 67:30)."],
       ["জীবন মানের পরীক্ষা: “কে তোমাদের মধ্যে আমলের দিক থেকে উত্তম” (৬৭:২)।","সৃষ্টিকে মনোযোগ দিয়ে দেখা ঈমান মজবুত করে।","গোপন আচরণই সবচেয়ে গুরুত্বপূর্ণ (৬৭:১২–১৩)।","পানি, খাবার ও নিরাপত্তা মনে করায় যে প্রতিদিন আমরা আল্লাহর ওপর নির্ভরশীল (৬৭:২১, ৬৭:৩০)।"]),
 example=("During a drought or a water outage, people suddenly notice how much depends on one tap. The last verse of this surah asks the same question in ordinary times.",
          "খরা বা পানি সরবরাহ বন্ধ থাকলে মানুষ হঠাৎ বুঝতে পারে, একটি কলের ওপর কত কিছু নির্ভর করে। এই সূরার শেষ আয়াত স্বাভাবিক সময়েই সেই প্রশ্ন করে।"))

N[76] = dict(
 short=("Man: created from almost nothing, shown the way, and the people who feed others for Allah alone.",
        "মানুষ: প্রায় কিছু না থেকে সৃষ্টি, পথ দেখানো, আর যারা শুধু আল্লাহর জন্য অন্যকে খাওয়ায়।"),
 ov=("Al-Insan (also called ad-Dahr) asks whether there was a time when the human being was nothing worth mentioning. Allah created him from a mixed drop to test him, gave him hearing and sight, and showed him the way, whether he is grateful or ungrateful. Then comes a portrait of the righteous: they keep their vows, fear a Day whose harm spreads wide, and feed the poor, the orphan and the captive out of love for Him, saying, “We feed you only for the sake of Allah; we seek from you neither reward nor gratitude.” A long description of the garden follows, then instructions to the Prophet ﷺ: be patient, remember your Lord morning and evening, and pray at night.",
     "সূরা আল-ইনসান (একে আদ-দাহরও বলা হয়) প্রশ্ন করে, মানুষের ওপর কি এমন সময় আসেনি, যখন সে উল্লেখযোগ্য কিছুই ছিল না? আল্লাহ তাকে মিশ্র শুক্রবিন্দু থেকে সৃষ্টি করেছেন পরীক্ষা করার জন্য, তাকে শ্রবণ ও দৃষ্টি দিয়েছেন, এবং পথ দেখিয়েছেন — সে কৃতজ্ঞ হোক বা অকৃতজ্ঞ। তারপর সৎকর্মশীলদের ছবি: তারা মানত পূর্ণ করে, এমন দিনকে ভয় করে যার অনিষ্ট ব্যাপক, আর তাঁর ভালোবাসায় অভাবী, এতিম ও বন্দিকে খাওয়ায় — বলে, “শুধু আল্লাহর সস্তুষ্টি লাভের উদ্দেশ্যে আমরা তোমাদেরকে খাবার দান করি, আমরা তোমাদের কাছ থেকে প্রতিদান চাই না, কৃতজ্ঞতাও নয়” এরপর জান্নাতের দীর্ঘ বর্ণনা, আর নবী ﷺ-এর প্রতি নির্দেশ: ধৈর্য ধরো, সকাল-সন্ধ্যা রবের নাম স্মরণ করো, রাতে ইবাদত করো।"),
 flow=[(1,3,"From nothing worth mentioning; tested and shown the way","উল্লেখযোগ্য কিছু না থেকে; পরীক্ষা ও পথনির্দেশ"),
       (4,10,"The righteous: keeping vows and feeding others for Allah alone","সৎকর্মশীলরা: মানত পূরণ ও শুধু আল্লাহর জন্য খাওয়ানো"),
       (11,22,"The reward: a garden, shade and drink; “your efforts have been appreciated”","প্রতিদান: বাগান, ছায়া ও পানীয়; “তোমাদের কর্মপ্রচেষ্টা ছিল প্রসংশাযোগ্য”"),
       (23,31,"Patience, remembrance, night prayer; a reminder for whoever wills","ধৈর্য, স্মরণ, রাতের নামাজ; যে চায় তার জন্য উপদেশ")],
 concepts=[("Shakir or kafur","শাকির বা কাফুর","Grateful or ungrateful: after being shown the way, a person chooses.","কৃতজ্ঞ বা অকৃতজ্ঞ: পথ দেখানোর পর মানুষ নিজে বেছে নেয়।","76:3","q"),
           ("Giving what they love","প্রিয় জিনিস দান","Rowwad translates 76:8 as giving food “despite their love for it”; Pickthall reads “for love of Him”. Translators differ here; either way the givers want no reward or thanks from people (76:9).","৭৬:৮-এ খাবারের প্রতি নিজেদের ভালোবাসা থাকা সত্ত্বেও দান করার কথা আছে (কোনো কোনো অনুবাদে ‘তাঁর ভালোবাসায়’); দুই ক্ষেত্রেই দাতারা মানুষের কাছে প্রতিদান বা কৃতজ্ঞতা চায় না (৭৬:৯)।","76:8–9","q")],
 take=(["Remembering that we once were nothing keeps us humble (76:1).","Generosity is most beautiful when it expects nothing back (76:9).","Our efforts are seen and appreciated by Allah (76:22).","Morning and evening remembrance and night prayer give strength for patience (76:24–26)."],
       ["একসময় আমরা কিছুই ছিলাম না — এই স্মরণ বিনয়ী রাখে (৭৬:১)।","প্রতিদান না চেয়ে দান সবচেয়ে সুন্দর (৭৬:৯)।","আমাদের প্রচেষ্টা আল্লাহ দেখেন ও মূল্যায়ন করেন (৭৬:২২)।","সকাল-সন্ধ্যার যিকির ও রাতের নামাজ ধৈর্যের শক্তি দেয় (৭৬:২৪–২৬)।"]),
 example=("Volunteering at a food bank without posting about it, or cooking for a new neighbour without expecting anything in return, matches the attitude of verse 9.",
          "কারও কাছে না বলে খাদ্য ব্যাংকে স্বেচ্ছাসেবা করা, বা নতুন প্রতিবেশীর জন্য রান্না করে কিছু আশা না করা — ৯ নম্বর আয়াতের মনোভাবের সঙ্গে মেলে।"))
